/// `paths` drawn in a 24x24 stroke icon; `class` sizes it (`size-4`).
pub fn icon(paths: &'static str, class: &'static str) -> impl IntoView {
    let svg = format!(
        r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-full h-full">{paths}</svg>"#
    );
    view! { <span class=format!("inline-block shrink-0 {class}") inner_html=svg></span> }
}
